INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 3, 'theory', 'Quiz: sorting and LIMIT');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 0, 'What happens if you run SELECT * FROM products LIMIT 3 without ORDER BY?', '["The three cheapest products are returned", "Any three rows are returned: which ones is not guaranteed", "An error: LIMIT requires ORDER BY", "The three latest records are returned"]', 1, 'A result without ORDER BY has no order, so LIMIT cuts off arbitrary rows. For a top list you always need an explicit sort.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 1, 'How does NULL behave in SQLite with ORDER BY price ASC?', '["It comes last", "It comes first: NULL is considered the smallest", "It is excluded from the result", "It causes an error"]', 1, 'In SQLite, NULL is less than any value: with ASC it comes first, with DESC last. You can control the position explicitly with NULLS FIRST / NULLS LAST.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 2, 'Which query returns the third page of 10 rows?', '["LIMIT 10 OFFSET 30", "LIMIT 10 OFFSET 20", "LIMIT 30 OFFSET 10", "LIMIT 20 OFFSET 10"]', 1, 'Offset = (page number - 1) × page size = 2 × 10 = 20.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 3, 'Why is it useful to use a unique column as the second sort key?', '["It speeds up the query a thousand times", "The order of rows that tie on the first key becomes unambiguous", "Without it SQL raises an error", "It removes empty values"]', 1, 'If the first key has repeats, the order among equal rows is undefined. A unique second key makes the result reproducible, which matters for pages and top lists.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 3, 4, 'In what order does the database execute the parts of a query?', '["ORDER BY → WHERE → SELECT → LIMIT", "FROM → WHERE → SELECT/DISTINCT → ORDER BY → LIMIT", "SELECT → FROM → LIMIT → ORDER BY", "LIMIT → ORDER BY → WHERE → FROM"]', 1, 'First FROM and WHERE, then SELECT (and DISTINCT) is computed, then the sort, and LIMIT/OFFSET at the very end. That is why ORDER BY sees aliases, while WHERE does not.');
